import{_ as a,o as n,c as e,ae as p}from"./chunks/framework.Iv6F95cJ.js";const h=JSON.parse('{"title":"http conf","description":"","frontmatter":{},"headers":[],"relativePath":"books/http-insight/41 - Linux-Mac实验环境搭建与URI查询参数.md","filePath":"books/http-insight/41 - Linux-Mac实验环境搭建与URI查询参数.md"}'),t={name:"books/http-insight/41 - Linux-Mac实验环境搭建与URI查询参数.md"};function i(o,s,l,r,c,d){return n(),e("div",null,[...s[0]||(s[0]=[p(`<p>你好，我是Chrono。</p><p>先要说一声“抱歉”。由于工作比较紧张、项目实施频繁出差，导致原本预定的“答疑篇”迟迟没有进展，这次趁着“十一”长假，总算赶出了两期，集中回答几个同学们问得比较多的问题：Linux/Mac实验环境搭建（<a href="https://time.geekbang.org/column/article/100124" target="_blank" rel="noreferrer">第7讲</a>），URI查询参数（<a href="https://time.geekbang.org/column/article/102008" target="_blank" rel="noreferrer">第11讲</a>），还有DHE/ECDHE算法的原理（<a href="https://time.geekbang.org/column/article/110354" target="_blank" rel="noreferrer">第26讲</a>），后续有时间可能还会再陆续补充完善。</p><p>很高兴在时隔一个多月后与你再次见面，废话不多说了，让我们开始吧。</p><h2 id="linux上搭建实验环境" tabindex="-1">Linux上搭建实验环境 <a class="header-anchor" href="#linux上搭建实验环境" aria-label="Permalink to &quot;Linux上搭建实验环境&quot;">&amp;ZeroWidthSpace;</a></h2><p>我们先来看一下如何在Linux上搭建课程的实验环境。</p><p>首先，需要安装OpenResty，但它在Linux上提供的不是zip压缩包，而是各种Linux发行版的预编译包，支持常见的Ubuntu、Debian、CentOS等等，而且<a href="http://openresty.org/cn/linux-packages.html" target="_blank" rel="noreferrer">官网</a>上有非常详细安装步骤。</p><p>以Ubuntu为例，只要“按部就班”地执行下面的几条命令就可以了，非常轻松：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 安装导入GPG公钥所需的依赖包：</span></span>
<span class="line"><span>sudo apt-get -y install --no-install-recommends wget gnupg ca-certificates</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span># 导入GPG密钥：</span></span>
<span class="line"><span>wget -O - https://openresty.org/package/pubkey.gpg | sudo apt-key add -</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span># 安装add-apt-repository命令</span></span>
<span class="line"><span>sudo apt-get -y install --no-install-recommends software-properties-common</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span># 添加官方仓库：</span></span>
<span class="line"><span>sudo add-apt-repository -y &quot;deb http://openresty.org/package/ubuntu $(lsb_release -sc) main&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span># 更新APT索引：</span></span>
<span class="line"><span>sudo apt-get update</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span># 安装 OpenResty</span></span>
<span class="line"><span>sudo apt-get -y install openresty</span></span></code></pre></div><p>全部完成后，OpenResty会安装到“/usr/local/openresty”目录里，可以用它自带的命令行工具“resty”来验证是否安装成功：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$resty -v</span></span>
<span class="line"><span>resty 0.23</span></span>
<span class="line"><span>nginx version: openresty/1.15.8.2</span></span>
<span class="line"><span>built with OpenSSL 1.1.0k  28 May 2019</span></span></code></pre></div><p>有了OpenResty，就可以从GitHub上获取http_study项目的源码了，用“git clone”是最简单快捷的方法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/chronolaw/http_study</span></span></code></pre></div><p>在Git仓库的“www”目录，我为Linux环境补充了一个Shell脚本“run.sh”，作用和Windows下的start.bat、stop.bat差不多，可以简单地启停实验环境，后面可以接命令行参数start/stop/reload/list：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd http_study/www/    #脚本必须在www目录下运行，才能找到nginx.conf</span></span>
<span class="line"><span>./run.sh start        #启动实验环境</span></span>
<span class="line"><span>./run.sh list         #列出实验环境的Nginx进程</span></span>
<span class="line"><span>./run.sh reload       #重启实验环境</span></span>
<span class="line"><span>./run.sh stop         #停止实验环境</span></span></code></pre></div><p>启动OpenResty之后，就可以用浏览器或者curl来验证课程里的各个测试URI，但之前不要忘记修改“/etc/hosts”添加域名解析，例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>curl -v &quot;http://127.0.0.1/&quot;</span></span>
<span class="line"><span>curl -v &quot;http://www.chrono.com/09-1&quot;</span></span>
<span class="line"><span>curl -k &quot;https://www.chrono.com/24-1?key=1234&quot;</span></span>
<span class="line"><span>curl -v &quot;http://www.chrono.com/41-1&quot;</span></span></code></pre></div><h2 id="mac上搭建实验环境" tabindex="-1">Mac上搭建实验环境 <a class="header-anchor" href="#mac上搭建实验环境" aria-label="Permalink to &quot;Mac上搭建实验环境&quot;">&amp;ZeroWidthSpace;</a></h2><p>看完了Linux，我们再来看一下Mac。</p><p>这里我用的是两个环境：Mac mini 和 MacBook Air，不过都是好几年前的“老古董”了，系统是10.13 High Sierra和10.14 Mojave（更早的版本没有测试，但应该也都可以）。</p><p>首先要保证Mac里有第三方包管理工具homebrew，可以用下面的命令安装：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#先安装Mac的homebrew</span></span>
<span class="line"><span>/usr/bin/ruby -e &quot;$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/master/install)&quot;</span></span></code></pre></div><p>然后，要用homebrew安装OpenResty，但它在Mac上的安装过程和Linux不同，不是预编译包，而是要下载许多相关的源码（如OpenSSL），然后再用clang本地编译，大概要花上五六分钟的时间，整体上比较慢，要有点耐心。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#使用homebrew安装OpenResty</span></span>
<span class="line"><span>brew install openresty/brew/openresty</span></span></code></pre></div><p>安装完OpenResty，后续的操作就和Linux一样了，“git clone”项目源码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/chronolaw/http_study</span></span></code></pre></div><p>然后，进“http_study/www”目录，用脚本“run.sh”启停实验环境，用Safari或者curl测试。</p><h2 id="linux-mac下的抓包" tabindex="-1">Linux/Mac下的抓包 <a class="header-anchor" href="#linux-mac下的抓包" aria-label="Permalink to &quot;Linux/Mac下的抓包&quot;">&amp;ZeroWidthSpace;</a></h2><p>Linux和Mac里都有图形界面版本的Wireshark，抓包的用法与Windows完全一样，简单易用。</p><p>所以，今天我主要介绍命令行形式的抓包。</p><p>命令行抓包最基本的方式就是著名的tcpdump，不过我用得不是很多，所以就尽可能地“藏拙”了。</p><p>简单的抓包使用“-i lo”指定抓取本地环回地址，“port”指定端口号，“-w”指定抓包的存放位置，抓包结束时用“Ctrl+C”中断：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo tcpdump -i lo -w a.pcap</span></span>
<span class="line"><span>sudo tcpdump -i lo port 443 -w a.pcap</span></span></code></pre></div><p>抓出的包也可以用tcpdump直接查看，用“-r”指定包的名字：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcpdump -r a.pcap </span></span>
<span class="line"><span>tcpdump -r 08-1.pcapng -A</span></span></code></pre></div><p>不过在命令行界面下可以用一个更好的工具——tshark，它是Wireshark的命令行版本，用法和tcpdump差不多，但更易读，功能也更丰富一些。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tshark -r 08-1.pcapng </span></span>
<span class="line"><span>tshark -r 08-1.pcapng -V</span></span>
<span class="line"><span>tshark -r 08-1.pcapng -O tcp|less</span></span>
<span class="line"><span>tshark -r 08-1.pcapng -O http|less</span></span></code></pre></div><p>tshark也支持使用keylogfile解密查看HTTPS的抓包，需要用“-o”参数指定log文件，例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tshark -r 26-1.pcapng -O http -o ssl.keylog_file:26-1.log|less</span></span></code></pre></div><p>tcpdump、tshark和Linux里的许多工具一样，参数繁多、功能强大，你可以课后再找些资料仔细研究，这里就不做过多地介绍了。</p><h2 id="uri的查询参数和头字段" tabindex="-1">URI的查询参数和头字段 <a class="header-anchor" href="#uri的查询参数和头字段" aria-label="Permalink to &quot;URI的查询参数和头字段&quot;">&amp;ZeroWidthSpace;</a></h2><p>在<a href="https://time.geekbang.org/column/article/102008" target="_blank" rel="noreferrer">第11讲</a>里我留了一个课下作业：</p><p>“URI的查询参数和头字段很相似，都是key-value形式，都可以任意自定义，那么它们在使用时该如何区别呢？”</p><p>从课程后的留言反馈来看，有的同学没理解这个问题的本意，误以为问题问的是这两者在表现上应该如何区分，比如查询参数是跟在“？”后面，头字段是请求头里的KV对。</p><p>这主要是怪我没有说清楚。这个问题实际上想问的是：查询参数和头字段两者的形式很相近，query是key-value，头字段也是key-value，它们有什么区别，在发送请求时应该如何正确地使用它们。</p><p>换个说法就是：应该在什么场景下恰当地自定义查询参数或者头字段来附加额外信息。</p><p>当然了，因为HTTP协议非常灵活，这个问题也不会有唯一的、标准的答案，我只能说说我自己的理解。</p><p>因为查询参数是与URI关联在一起的，所以它针对的就是资源（URI），是长期、稳定的。而头字段是与一次HTTP请求关联的，针对的是本次请求报文，所以是短期、临时的。简单来说，就是两者的作用域和时效性是不同的。</p><p>从这一点出发，我们就可以知道在哪些场合下使用查询参数和头字段更加合适。</p><p>比如，要获取一个JS文件，而它会有多个版本，这个“版本”就是资源的一种属性，应该用查询参数来描述。而如果要压缩传输、或者控制缓存的时间，这些操作并不是资源本身固有的特性，所以用头字段来描述更好。</p><p>除了查询参数和头字段，还可以用其他的方式来向URI发送附加信息，最常用的一种方式就是POST一个JSON结构，里面能够存放比key-value复杂得多的数据，也许你早就在实际工作中这么做了。</p><p>在这种情况下，就可以完全不使用查询参数和头字段，服务器从JSON里获取所有必需的数据，让URI和请求头保持干净、整洁（^_^）。</p><p>今天的答疑就先到这里，我们下期再见，到时候再讲ECDHE算法。</p><p><img src="https://static001.geekbang.org/resource/image/c1/f9/c17f3027ba3cfb45e391107a8cf04cf9.png?wh=1769%2A2606" alt="unpreview" loading="lazy" referrerpolicy="no-referrer"> 精选留言（15） 浪里淘沙的小法师 👍（25） 💬（1）讲一下用M1芯片 mac 搭建搭建环境的遇到的问题和解决方法。</p><ol><li><p>运行 ./run.sh start 报错 /usr/local/bin/openresty: command not found 这是因为 M1 芯片mac 的 homebrew 安装软件的位置与以往不同，先通过 which openresty 查询 openresty 的位置 /opt/homebrew/bin/openresty，然后打开 run.sh 脚本替换一下老师写的位置 if [ $os != &quot;Linux&quot; ] ; then openresty=&quot;/usr/local/bin/openresty&quot; fi 替换成 if [ $os != &quot;Linux&quot; ] ; then openresty=&quot;/opt/homebrew/bin/openresty&quot; fi</p></li><li><p>再运行 ./run.sh start 报错 nginx: [emerg] could not build server_names_hash, you should increase server_names_hash_bucket_size: 32 网上查寻了一下，放大 bucket_size 即可，打开 www/conf/nginx.conf 文件添加这一句server_names_hash_bucket_size 64; 即可</p></li></ol><h1 id="http-conf" tabindex="-1">http conf <a class="header-anchor" href="#http-conf" aria-label="Permalink to &quot;http conf&quot;">&amp;ZeroWidthSpace;</a></h1><p>http { #include http/common.conf; #include http/cache.conf; #include http/resty.conf; #include http/mime.types; server_names_hash_bucket_size 64;</p><pre><code>include     http&amp;#47;*.conf;

include     http&amp;#47;servers&amp;#47;*.conf;
</code></pre><p>}2021-11-10GitHubGanKai 👍（7） 💬（2）真好，又见到你了，而且我最近换个了mac，😊正愁这个。2019-10-09Luka!3055 👍（3） 💬（1）记录下问题：</p><p>brew install openresty/brew/openresty 后，报错： curl: (7) Failed to connect to raw.githubusercontent.com port 443: Connection refused Error: An exception occurred within a child process: DownloadError: Failed to download resource &quot;openresty-openssl--patch&quot; Download failed: https://raw.githubusercontent.com/openresty/openresty/master/patches/openssl-1.1.0d-sess_set_get_cb_yield.patch</p><p>此时把 DNS 设置为 114.114.114.114 或者 8.8.8.8 就好了，最好再挂个梯子2020-05-07dongge 👍（2） 💬（2）老师好， 按文章指导搭建了MAC的环境： openresty -v nginx version: openresty/1.11.2.2</p><p>在~/git/http_study/www目录下执行 ./run.sh start Password: nginx: [emerg] &quot;/Users/xiaodong/git/http_study/www/conf/ssl/ticket.key&quot; must be 48 bytes in /Users/xiaodong/git/http_study/www/conf/nginx.conf:34 报了这个错误，在网上google没找到解决方法。 尝试在nginx.conf中注销相关代码，也会报其他错误。 老师能指点一下吗？2019-10-18dongge 👍（2） 💬（1）这个专栏这么好玩，留言的人这么少，真可惜。 2019-10-16ifelse 👍（1） 💬（1）谢谢分享2023-02-09Change 👍（1） 💬（7）老师请教个问题：Mac 环境下安装以后，按照命令./run.sh start 启动后访问 localhost 显示403 Forbidden：终端返回的错误信息是下面的错误信息，这是所有端口都被占用了？我查了一下好像也没有被占用啊，不知道这是啥原因 nginx: [emerg] bind() to 0.0.0.0:80 failed (48: Address already in use) nginx: [emerg] bind() to 0.0.0.0:8080 failed (48: Address already in use) nginx: [emerg] bind() to 0.0.0.0:443 failed (48: Address already in use) nginx: [emerg] bind() to 0.0.0.0:8443 failed (48: Address already in use) nginx: [emerg] bind() to 0.0.0.0:440 failed (48: Address already in use) nginx: [emerg] bind() to 0.0.0.0:441 failed (48: Address already in use) nginx: [emerg] bind() to 0.0.0.0:442 failed (48: Address already in use) 2020-03-28SmNiuhe 👍（1） 💬（6）这个大家有遇到嘛，是不是资源的问题 brew install openresty/brew/openresty ：DownloadError: Failed to download resource &quot;openresty-openssl--patch&quot; Download failed: https://raw.githubusercontent.com/openresty/openresty/master/patches/openssl-1.1.0d-sess_set_get_cb_yield.patch2019-11-07超轶主 👍（0） 💬（2）mac环境运行 run run.sh 返回 nginx version: openresty/1.19.9.1 format : run.sh [start|stop|reload|list]是什么情况呢2021-12-13silence 👍（0） 💬（3）请问安装好环境后在www目录执行./run.sh start 老是command not found怎么解决2021-08-23Miroticwillbeforever 👍（0） 💬（2）老师我有个问题。实验环境搭建好了。前两讲的实验也做成功了。 但是当我用浏览器 访问 www.chrono.com 时，它跳转到的 地址为 https://dp.diandongzhi.com/?acct=660&amp;site=chrono.com 然后wireshark抓包并没有任何反应。我想问一下是我操作不当的原因还是怎么回事。课程大部分听完了。但是后面实验没做成挺难受的，没有去验证。等老师给个答复准备二刷！2021-06-22武安君 👍（0） 💬（1）老师你好、我安装好了openrestry后、启动服务说 nginx：invalid option：http，请问是怎么回事呀2021-03-20小童 👍（0） 💬（2）不行啊，老师，我的那个openresty界面出来了，就是抓不到包！用的wireshark .搞了好久。那个telnet也安装了。是不是那步出错了 ，我就直接运行openresty，然后用抓包工具过滤信息，然后浏览器输入localhost，浏览器洁界面也出来了。2021-03-02旗木卡卡 👍（0） 💬（3）Mac电脑，耗费本人2个晚上的环境，终于搭好了，碰到了2个坑，第一个是dns查找不到，brew install openresty时，需要在本机的hosts文件，加上解析不到的url的ip地址，第二个是启动一直bind不上，nginx就自动启动了，但是很明显不是openresty，然后用root权限启动成功，也可以正常访问，发现是nginx.conf的user权限问题，修改成本机的用户user kaka(你的用户名) staff;即可。 2020-08-19Jinlee 👍（0） 💬（1）Welcome to HTTP Study Page! 还好我看得迟，成功在ubuntu下搭建起环境😊😊😊2020-04-21</p>`,61)])])}const g=a(t,[["render",i]]);export{h as __pageData,g as default};
